<script setup lang="ts">import type {Prediction} from '../types/domain';import {fixed} from '../utils/format';defineProps<{rows:Prediction[]}>();defineEmits<{select:[id:string]}>()</script><template><div class="table-wrap"><table><thead><tr><th>待估点</th><th>x / y 米</th><th>预测含水率%</th><th>空间方差 pp²</th><th>空间SD pp</th><th></th></tr></thead><tbody><tr v-for="p in rows" :key="p.query_id"><td>{{p.query_id}}</td><td>{{fixed(p.x,1)}} / {{fixed(p.y,1)}}</td><td>{{fixed(p.prediction)}}</td><td>{{fixed(p.variance,5)}}</td><td>{{fixed(p.standard_deviation)}}</td><td><button class="table-action" @click="$emit('select',p.query_id)">权重</button></td></tr></tbody></table></div></template>
